    "id": "superexam-physiology-0048",
    "subject": "physiology",
    "originalNumber": 48,
    "stem": "Breathing pure oxygen at high altitude causes",
    "choices": [
      {
        "label": "A",
        "text": "Lower fraction of inspired nitrogen"
      },
      {
        "label": "B",
        "text": "Lower fraction of inspired oxygeb"
      },
      {
        "label": "C",
        "text": "Higher atmospheric barometric pressure"
      },
      {
        "label": "D",
        "text": "Decrease in alveolar dead space ventilation"
      },
      {
        "label": "E",
        "text": "AOTA"
      }
    ],
    "correctChoice": "A",
    "explanation": "Breathing pure O2 lowers FiO2 of nitrogen. At higher\naltitudes, the partial pressure of the gases decreases.",
